#!/usr/bin/env bash
# Reproduce the semantic-soundness and C5 probes of REPORT.md (dimension 3 / C5 evidence).
#   P-SEM : 41 edge inputs (shift >= width / negative, div/rem by 0, MIN/-1, wrap, casts,
#           negative Array::make, UTF-8 String.length, Bytes OOB) evaluated natively and in the
#           Lean model generated by `pionc extract-lean`; outputs must be byte-identical.
#   P-NV  : the same shift/div outside `#verify` (native masks / returns 0 instead of trapping).
#   P-B64 : base64 length helpers overflow above the domain the theorems assume.
#   P-CRDT: crdt delete ranges wrap above the domain the theorems assume.
# Usage: probes/run_probes.sh <pion-packages checkout> [LEAN_WORK]
#   LEAN_WORK must already hold proj/PionLean and an Aeneas build (see REPORT.md 2.2); without
#   it only the native halves run.
set -euo pipefail
REPO="$(cd "${1:?repo}" && pwd)"
LEAN_WORK="${2:-}"
HERE="$(cd "$(dirname "$0")" && pwd)"
export PATH="$HOME/.pion/bin:$HOME/.elan/bin:$PATH"
T="$(mktemp -d /private/tmp/rt-lean-audit-probe.XXXXXX)"
trap 'rm -rf "$T"' EXIT
export PION_CACHE_DIR="$T/cas"

echo "=== P-SEM native ==="
mkdir -p "$T/probe/src"
cp "$HERE/semantics/pion.toml" "$T/probe/pion.toml"
cp "$HERE/semantics/src/lib.pion" "$T/probe/src/lib.pion"
python3 -I - "$T" "$HERE/semantics/cases.json" <<'EOF'
import json, os, subprocess, sys
T, spec = sys.argv[1], sys.argv[2]
cases = json.load(open(spec))
out = []
for i, (f, pa, la) in enumerate(cases):
    d = f'{T}/c{i:02d}'
    os.makedirs(d + '/src', exist_ok=True)
    open(d + '/pion.toml', 'w').write(f'[package]\nname = "c{i:02d}"\nversion = "0.1.0"\n\n[dependencies]\nprobe = {{ path = "{T}/probe" }}\n')
    pre, args = '', pa
    if 'BYTES200' in pa:
        pre = '  let bb = Bytes::new(1)\n  bb[0] = (200).to_byte()\n'
        args = pa.replace('BYTES200', 'bb')
    label = f'case{i:02d} {f}({pa.replace(chr(34), "")}) = '
    open(d + '/src/main.pion', 'w').write('import "probe"\n\nfn main(w : World) -> Unit {\n' + pre +
        f'  let r = probe::{f}({args})\n  io_println(w, "{label}" + r.to_string())\n}}\n')
    subprocess.run(['pionc', 'build', '-o', d + '/bin', d], check=True, capture_output=True)
    r = subprocess.run([d + '/bin'], capture_output=True, text=True)
    out.append(label + 'PANIC' if r.returncode != 0 else r.stdout.strip())
open(f'{T}/native.out', 'w').write('\n'.join(out) + '\n')
# Lean side source
L = ['import Aeneas', 'import PionLean', 'import Probe.Types', 'import Probe.Funs', 'open Aeneas Aeneas.Std Result Pion probe', '',
     'def showI {t} (r : Result (Std.IScalar t)) : String := match r.match with | .ok v => toString v.val | _ => "PANIC"',
     'def showU {t} (r : Result (Std.UScalar t)) : String := match r.match with | .ok v => toString v.val | _ => "PANIC"',
     'def BYTES200 : Pion.Bytes := ⟨[200#u8]⟩', '']
rows = []
for i, (f, pa, la) in enumerate(cases):
    show = 'showU' if f in ('v_u_shr', 'v_int_to_uint') else 'showI'
    rows.append(f'  s!"case{i:02d} {f}({pa.replace(chr(34), "")}) = {{{show} ({f} {la})}}"')
L.append('def runAll : List String := [\n' + ',\n'.join(rows) + '\n]')
L.append('#eval do for l in runAll do IO.println l')
open(f'{T}/ProbeEval.lean', 'w').write('\n'.join(L) + '\n')
EOF
diff -u "$HERE/semantics/expected_native.out" "$T/native.out" && echo "native output matches the recorded run"

if [ -n "$LEAN_WORK" ] && [ -d "$LEAN_WORK/proj/PionLean" ]; then
  echo "=== P-SEM Lean model ==="
  pionc extract-lean "$T/probe" --out "$LEAN_WORK/proj" >/dev/null
  cp "$T/ProbeEval.lean" "$LEAN_WORK/proj/ProbeEval.lean"
  cat > "$LEAN_WORK/proj/lakefile.lean" <<'EOF'
import Lake
open Lake DSL
require aeneas from "./.deps/aeneas"
package «pionlean» where
  leanOptions := #[⟨`weak.linter.dupNamespace, false⟩]
@[default_target] lean_lib PionLean
lean_lib Probe
EOF
  (cd "$LEAN_WORK/proj" && lake build PionLean Probe.Types Probe.Funs >/dev/null && lake env lean ProbeEval.lean) > "$T/lean.out"
  diff -u "$T/native.out" "$T/lean.out" && echo "P-SEM: native == Lean model on all $(wc -l < "$T/native.out" | tr -d ' ') edge cases"
  rm -rf "$LEAN_WORK/proj/Probe" "$LEAN_WORK/proj/ProbeEval.lean"
fi

echo "=== P-NV (same operations outside #verify) ==="
mkdir -p "$T/nv/src"
printf '[package]\nname = "nv"\nversion = "0.1.0"\n\n[dependencies]\n' > "$T/nv/pion.toml"
cp "$HERE/semantics/nonverify_main.pion" "$T/nv/src/main.pion"
pionc build -o "$T/nv/bin" "$T/nv" >/dev/null && "$T/nv/bin"

for p in crdt:crdt_wrap base64:base64_overflow; do
  pkg="${p%%:*}"; f="${p##*:}"
  echo "=== P-$(echo "$pkg" | tr a-z A-Z) ==="
  mkdir -p "$T/$f/src"
  printf '[package]\nname = "p%s"\nversion = "0.1.0"\n\n[dependencies]\n%s = { path = "%s/packages/%s" }\n' "$pkg" "$pkg" "$REPO" "$pkg" > "$T/$f/pion.toml"
  cp "$HERE/c5/$f.pion" "$T/$f/src/main.pion"
  pionc build -o "$T/$f/bin" "$T/$f" >/dev/null
  "$T/$f/bin" || echo "(exit $? — expected for base64: negative Bytes length panic)"
done
